// Valida pedido e monta SQL (dono sanitizado, periodo whitelist)
const body = items[0].json.body || items[0].json;
const dono = String(body.dono || '').replace(/[^0-9]/g, '');
const periodos = ['hoje','semana','mes','mes_passado','tudo'];
const periodo = periodos.includes(body.periodo) ? body.periodo : 'mes';
if (!dono) return [];

const hojeLocal = "(NOW() AT TIME ZONE d.timezone)::date";
let filtro;
if (periodo === 'hoje') filtro = `g0.data_gasto = ${hojeLocal}`;
else if (periodo === 'semana') filtro = `g0.data_gasto >= ${hojeLocal} - 6`;
else if (periodo === 'mes') filtro = `date_trunc('month', g0.data_gasto) = date_trunc('month', ${hojeLocal})`;
else if (periodo === 'mes_passado') filtro = `date_trunc('month', g0.data_gasto) = date_trunc('month', ${hojeLocal} - INTERVAL '1 month')`;
else filtro = 'TRUE';

const sql = `SELECT d.numero, d.nome, d.timezone, d.moeda,\n  (SELECT COALESCE(json_agg(json_build_object('id', g0.id, 'data', to_char(g0.data_gasto,'DD/MM/YYYY'), 'descricao', g0.descricao, 'categoria', COALESCE(g0.categoria,'outros'), 'forma', COALESCE(g0.forma_pagamento,''), 'valor', g0.valor, 'obs', COALESCE(g0.observacoes,''), 'sub', COALESCE(g0.subcategoria,'')) ORDER BY g0.data_gasto, g0.id), '[]'::json)\n   FROM giulia_gastos g0 WHERE g0.dono_numero = d.numero AND ${filtro}) AS gastos\nFROM giulia_donos d WHERE d.numero = '${dono}';`;

return [{ json: { dono, periodo, sql } }];

// Monta resumo texto + graficos (QuickChart, config JS com funcoes) + meta da planilha
const req = $('Preparar Pedido').first().json;
const d = (items[0] && items[0].json) || {};
const labelPeriodo = ({hoje:'hoje', semana:'ultimos 7 dias', mes:'mes atual', mes_passado:'mes passado', tudo:'periodo completo'})[req.periodo] || 'mes atual';
if (!d.numero) return [{ json: { vazio: true, dono: req.dono, texto: 'Nao consegui gerar o relatorio agora. Me pede de novo em instantes?' } }];
const gastos = typeof d.gastos === 'string' ? JSON.parse(d.gastos) : (d.gastos || []);
const SYM = d.moeda === 'USD' ? '$' : 'R$';
function fmt(v){ const n = Number(v) || 0; return SYM + ' ' + n.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.'); }
if (!gastos.length) return [{ json: { vazio: true, dono: d.numero, texto: `Nenhum gasto registrado no periodo (${labelPeriodo}).` } }];

const total = gastos.reduce((s,g) => s + (Number(g.valor)||0), 0);
const porCat = {};
for (const g of gastos) porCat[g.categoria] = (porCat[g.categoria]||0) + (Number(g.valor)||0);
let cats = Object.entries(porCat).sort((a,b) => b[1]-a[1]);
if (cats.length > 8) { const resto = cats.slice(7).reduce((s,c)=>s+c[1],0); cats = cats.slice(0,7); cats.push(['outros', resto]); }
const porDia = {};
for (const g of gastos) { const dd = String(g.data).substring(0,5); porDia[dd] = (porDia[dd]||0) + (Number(g.valor)||0); }
const dias = Object.entries(porDia);

// paleta categorica validada (ordem fixa, CVD-safe)
const CORES = ['#2a78d6','#1baf7a','#eda100','#008300','#4a3aa7','#e34948','#e87ba4','#eb6834'];
const pct = v => total ? Math.round(v/total*100) : 0;

// configs em JS literal (QuickChart aceita funcoes p/ datalabels e centro da rosca)
const catLabels = JSON.stringify(cats.map(([c,v]) => c + ' - ' + fmt(v)));
const catVals = JSON.stringify(cats.map(([c,v]) => Math.round(v*100)/100));
const catCores = JSON.stringify(CORES.slice(0, cats.length));
const cfgCat = "{type:'doughnut',data:{labels:" + catLabels + ",datasets:[{data:" + catVals + ",backgroundColor:" + catCores + ",borderColor:'#ffffff',borderWidth:3}]},options:{cutoutPercentage:58,layout:{padding:10},title:{display:true,text:'Gastos por categoria',fontSize:20,fontColor:'#0b0b0b',padding:14},legend:{position:'right',labels:{fontSize:13,fontColor:'#1f2937',padding:12,boxWidth:14}},plugins:{datalabels:{display:function(ctx){var d=ctx.dataset.data;var t=d.reduce(function(a,b){return a+b},0);return d[ctx.dataIndex]/t>=0.07;},formatter:function(v,ctx){var t=ctx.dataset.data.reduce(function(a,b){return a+b},0);return Math.round(v/t*100)+'%';},color:'#ffffff',font:{weight:'bold',size:15}},doughnutlabel:{labels:[{text:'" + fmt(total) + "',font:{size:22,weight:'bold'},color:'#0b0b0b'},{text:'total - " + labelPeriodo + "',font:{size:12},color:'#52514e'}]}}}}";

const diaLabels = JSON.stringify(dias.map(x=>x[0]));
const diaVals = JSON.stringify(dias.map(x=>Math.round(x[1]*100)/100));
const cfgDia = "{type:'bar',data:{labels:" + diaLabels + ",datasets:[{data:" + diaVals + ",backgroundColor:'#2a78d6',maxBarThickness:46}]},options:{layout:{padding:{top:28}},title:{display:true,text:'Gasto por dia - " + labelPeriodo + " (" + SYM + ")',fontSize:20,fontColor:'#0b0b0b',padding:14},legend:{display:false},scales:{yAxes:[{ticks:{beginAtZero:true,fontColor:'#52514e'},gridLines:{color:'#eef2f7',zeroLineColor:'#d7dfe9',drawBorder:false}}],xAxes:[{ticks:{fontColor:'#52514e'},gridLines:{display:false}}]},plugins:{datalabels:{anchor:'end',align:'end',offset:2,color:'#1f2937',font:{weight:'bold',size:12},formatter:function(v){var s=v>=1000?(Math.round(v/100)/10)+'k':String(v);return s.replace('.',',');}}}}}";

const qc = c => 'https://quickchart.io/chart?w=760&h=440&bkg=white&devicePixelRatio=2&c=' + encodeURIComponent(c);

const maior = gastos.reduce((m,g) => (Number(g.valor)||0) > (Number(m.valor)||0) ? g : m, gastos[0]);
const linhasCat = cats.map(([c,v]) => `  ${c}: ${fmt(v)} (${pct(v)}%)`).join('\n');
const agoraLocal = new Date().toLocaleString('sv-SE', { timeZone: d.timezone || 'America/Sao_Paulo' });
const dataFmt = agoraLocal.substring(8,10) + '/' + agoraLocal.substring(5,7) + '/' + agoraLocal.substring(0,4);
const nLanc = gastos.length === 1 ? '1 lancamento' : gastos.length + ' lancamentos';
const texto = `*Relatorio de gastos - ${labelPeriodo}*\n_Gerado em ${dataFmt}_\n\n*Total: ${fmt(total)}* (${nLanc})\n\n*Por categoria:*\n${linhasCat}\n\n*Maior gasto:* ${maior.descricao} - ${fmt(maior.valor)}\n\nSegue os graficos e a planilha completa.`;
const docname = `gastos-${req.periodo}-${dataFmt.replace(/\//g,'-')}.xlsx`;

return [{ json: { vazio: false, dono: d.numero, nome: d.nome || '', moeda: d.moeda || 'BRL', label_periodo: labelPeriodo, data_geracao: dataFmt, texto, chart_cat_url: qc(cfgCat), chart_dia_url: dias.length > 1 ? qc(cfgDia) : '', docname, gastos, total } }];

// Um item por midia (graficos) pra enviar em sequencia
const meta = $('Montar Meta').first().json;
const out = [];
if (meta.chart_cat_url) out.push({ json: { number: meta.dono, file: meta.chart_cat_url, caption: 'Como se distribui por categoria' } });
if (meta.chart_dia_url) out.push({ json: { number: meta.dono, file: meta.chart_dia_url, caption: 'Evolucao dia a dia' } });
return out;

// Gera XLSX premium (puro JS, sem libs) - relatorio de gastos
// Identidade: dark premium (#0B1A13 verde, #C9A84C dourado, #F5F0E8 creme)
// Duas abas: Resumo (capa + KPIs + categorias) e Lancamentos (tabela com filtro e cabecalho congelado)
'use strict';

// ---------- ZIP (STORE, sem compressao) ----------
const CRC_TABLE = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    t[n] = c;
  }
  return t;
})();
function crc32(buf) {
  let c = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xFF] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0;
}
function zipStore(entries) {
  const locals = [], centrals = [];
  let offset = 0;
  for (const e of entries) {
    const nameB = Buffer.from(e.name, 'utf8');
    const crc = crc32(e.data);
    const lh = Buffer.alloc(30);
    lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(0x0800, 6);
    lh.writeUInt16LE(0, 8); lh.writeUInt16LE(0, 10); lh.writeUInt16LE(0x21, 12);
    lh.writeUInt32LE(crc, 14); lh.writeUInt32LE(e.data.length, 18); lh.writeUInt32LE(e.data.length, 22);
    lh.writeUInt16LE(nameB.length, 26); lh.writeUInt16LE(0, 28);
    locals.push(lh, nameB, e.data);
    const ch = Buffer.alloc(46);
    ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(20, 4); ch.writeUInt16LE(20, 6);
    ch.writeUInt16LE(0x0800, 8); ch.writeUInt16LE(0, 10); ch.writeUInt16LE(0, 12); ch.writeUInt16LE(0x21, 14);
    ch.writeUInt32LE(crc, 16); ch.writeUInt32LE(e.data.length, 20); ch.writeUInt32LE(e.data.length, 24);
    ch.writeUInt16LE(nameB.length, 28);
    ch.writeUInt32LE(offset, 42);
    centrals.push(ch, nameB);
    offset += 30 + nameB.length + e.data.length;
  }
  const cdSize = centrals.reduce((s, b) => s + b.length, 0);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(entries.length, 8); eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(cdSize, 12); eocd.writeUInt32LE(offset, 16);
  return Buffer.concat([...locals, ...centrals, eocd]);
}

// ---------- helpers ----------
function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function colLetter(n) {
  let s = '';
  while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); }
  return s;
}

